INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_PROJECT_SPC_CLAIM_RESEARCH_NAME','认定科研专业'),('zh_Hans_CN','LOC_PROJECT_SPC_CLAIM_RESEARCH_DESCRIPTION','完成后，本城确立「科研」专业身份，获得 1 级专业潜力，其他专业认定项目随之移除。[NEWLINE][NEWLINE]项目须作为唯一生产目标持续 1 个完整回合。未分配及项目期间产生的生产力不会结转。读档后，仍符合条件的项目继续计时。改选其他生产目标后须重新计时。');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('en_US','LOC_PROJECT_SPC_CLAIM_RESEARCH_NAME','Claim Research Specialization'),('en_US','LOC_PROJECT_SPC_CLAIM_RESEARCH_DESCRIPTION','Establishes Research specialization at Potential Level 1 in this city. The other claim projects are removed.[NEWLINE][NEWLINE]Keep this as the only item in the Production queue for 1 full turn. The timer resumes after loading if the project still meets its requirements. Switching production targets resets the timer. Unassigned [ICON_Production] Production and Production earned during this project do not carry over.');
